INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 31, 'theory', 'Quiz: Future, Poll, Waker');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 31, 0, 'What must a future do before it returns Poll::Pending?', '["nothing special", "make sure the waker will be called later, when there is something to check", "call drop on itself", "block the thread"]', 1, 'Otherwise the executor will never poll the task again, and it hangs.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 31, 1, 'What is Context for in the poll method?', '["it stores the result", "it stores the call stack", "it gives access to the current task''s Waker", "it sets the priority"]', 2, 'cx.waker() is the handle you need to store or call.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 31, 2, 'What does thread::park do in a simple block_on?', '["puts the thread to sleep until an unpark, which the waker will call", "terminates the thread", "waits for user input", "changes the priority"]', 0, 'That way the thread does not burn the CPU in the polling loop.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 31, 3, 'Why do we save the freshest waker on every poll?', '["because the old one is always wrong", "because a Waker cannot be cloned", "to speed up compilation", "because the task may have been handed to another executor, and the new handle is the one to wake"]', 3, 'The Future contract allows the waker to change between polls.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 31, 4, 'What does the compiler turn an async fn with two .await points into?', '["two threads", "a finite state machine: an enum with several states", "a closure", "a call to sleep"]', 1, 'A future''s size is determined by the largest of its states.');
